"use strict";
// A class whose fields are assigned in the constructor and read through
// methods: the JS package's shape the npm-static lane compiles as typed TS.
class Store {
  constructor(host, port) {
    this.host = host;
    this.port = port;
    this.count = 0;
  }
  endpoint() {
    this.count++;
    return this.host + ":" + this.port;
  }
  label(prefix) {
    return prefix + this.endpoint();
  }
}
module.exports = { Store };
